import { beforeEach,describe,expect,it } from 'vitest';
import { EpicConnector } from '../epic.connector';import { X12GeneratorService } from '../../x12/x12-generator.service';import { X12ParserService } from '../../x12/x12-parser.service';
describe('Epic synthetic parity',()=>{let c:EpicConnector;beforeEach(async()=>{const g=new X12GeneratorService();c=new EpicConnector({} as any,{record:async()=>{}} as any,{baseUrl:'https://fhir.epic.test',tenantId:'t',clientId:'c'},g,new X12ParserService(g));await c.authorize('s')});it('supports demographics and FHIR synthetic sync',async()=>{const d:any=await c.getPatientDemographics('1');expect(d.patient.id).toMatch(/^ep_patient_/);const r=await c.syncFhirResources(['Patient','Appointment','Condition']);expect(r.synced).toBe(3);expect(r.resources[0].resourceType).toBe('Patient')});it('supports X12 billing extension',async()=>{const x=await c.submitClaim837P({patientMemberId:'S',cptCode:'90837',icd10Codes:['F32.9'],billedAmount:200,serviceDate:new Date('2026-01-01')});expect(x.x12).toContain('*ST*837P*0')})});
